from taf.sbts.oam.coam.admin import admin
from taf.ul.kpi_selector.btss.classical.Bts import Bts
from taf.ul.kpi_selector.operations.factory_prototype.exceptions import ConfigTypeNotFound


class OperationFactoryPrototype(object):
    def __init__(self):
        self.bts = None

    def setup_bts(self, tl, connection):
        """
        Sets up Bts instance for given testline and opens admin connection.
        :param tl: Testline object
        :type tl: Object of Testline from init file
        :param connection: AdminConnection object or if used, string name alias, 'admin' at default.
        :type connection: AdminConnection or str
        """
        self._open_admin_connection_depending_on_setup_type(tl, connection)
        self.bts = Bts(tl, connection)

    @staticmethod
    def _open_admin_connection_depending_on_setup_type(tl, connection):
        ad = admin()
        if tl.gnbs:
            username = tl.gnbs[0].cu.oam_http_connection_details.username
            password = tl.gnbs[0].cu.oam_http_connection_details.password
            ad.connect_to(bts_host=tl.gnbs[0].cu.oam_http_connection_details.addr,
                          bts_port=tl.gnbs[0].cu.oam_http_connection_details.port,
                          username=username if username else 'Nemuadmin',
                          password=password if password else 'nemuuser',
                          name=connection)
        elif tl.enbs:
            ad.connect_to(bts_host=tl.enbs[0].oam_ip.v4,
                          bts_port=443,
                          name=connection)
        else:
            raise ConfigTypeNotFound('Could not find gnbs nor enbs in configuration file. '
                                     'Please review your init file.')
